function generarReserva(cat) {
    const fixtures = BD_FIXTURES[cat]?.reserva || [];
    const equipos = BD_EQUIPOS[cat] || [];
    const catLabel = cat === 'oficial' ? 'TORNEO OFICIAL' : cat === 'promocional' ? 'TORNEO PROMOCIONAL' : cat === 'femenino' ? '1° FEMENINO' : cat === 'segundafemenino' ? '2° FEMENINO' : cat.toUpperCase();
    const maxFechas = cat === 'segundafemenino' ? 27 : 14;
    const n = estado.fecha || 1;

    // Visera playoffs según categoría
    const navDest = cat === 'oficial' ? 'reservaoficialplayoffs' : cat === 'promocional' ? 'reservapromocionalplayoffs' : cat === 'femenino' ? 'reservafemeninoplayoffs' : null;
    let html = navDest
        ? `<div onclick="navegar('${navDest}')" style="background:linear-gradient(135deg,#7b1a1a,#a93226);color:#fff;text-align:center;padding:9px 12px;font-size:12px;font-weight:bold;letter-spacing:0.5px;cursor:pointer;border-bottom:2px solid #f0a500;">🏆 Ver cuadro de Playoffs del Apertura ▶</div>`
        : '';

    // Fixture — igual que generarFixture pero leyendo de reserva
    let f = fixtures.find(x => x.fecha === n) || { partidos: [], libre: null };
    html += `<div class="nav-fechas">`;
    for (let i = 1; i <= maxFechas; i++) {
        const activa = i === n ? 'activa' : '';
        const tieneDatos = fixtures.some(x => x.fecha === i);
        html += `<div class="btn-f ${activa}" onclick="cambiarFechaReserva(${i},'${cat}')" style="${tieneDatos ? '' : 'color:#bbb;'}">${i}</div>`;
    }
    html += `</div>`;
    html += `<div class="header-t">RESERVA — ${catLabel} — FECHA ${n}</div>`;

    // Si no hay datos en reserva para esta fecha, usar el fixture del apertura (mismos partidos, sin resultados)
    // Solo para categorías cuya reserva comparte fixture con el principal (oficial, promocional)
    if (f.partidos.length === 0 && cat !== 'femenino' && cat !== 'segundafemenino') {
        const fApertura = (BD_FIXTURES[cat]?.apertura || BD_FIXTURES[cat]?.torneo2026 || []).find(x => x.fecha === n);
        if (fApertura) {
            f = { partidos: fApertura.partidos.map(p => ({...p, gl: null, gv: null})), libre: fApertura.libre };
        }
    }
    if (f.partidos.length === 0) {
        html += `<div class="msg-prox">Sin datos para esta fecha</div>`;
    } else {
    html += `<table>`;
    f.partidos.forEach(p => {
        const escL = equipos.find(e => e.nombre === p.l)?.clase || '';
        const escV = equipos.find(e => e.nombre === p.v)?.clase || '';
        if (p.gl === null) {
            html += `<tr>
                <td class="c-loc"><span style="direction:ltr;display:inline-flex;align-items:center;justify-content:flex-end;width:100%;">${p.l} <div class="escudo ${escL}" style="display:inline-block;vertical-align:middle;margin-left:4px;"></div></span></td>
                <td class="c-res">- -</td>
                <td class="c-vis"><div class="escudo ${escV}" style="display:inline-block;vertical-align:middle;margin-right:4px;"></div> ${p.v}</td>
            </tr>`;
        } else {
            html += `<tr>
                <td class="c-loc"><span style="direction:ltr;display:inline-flex;align-items:center;justify-content:flex-end;width:100%;">${p.l} <div class="escudo ${escL}" style="display:inline-block;vertical-align:middle;margin-left:4px;"></div></span></td>
                <td class="c-res">${p.gl} - ${p.gv}</td>
                <td class="c-vis"><div class="escudo ${escV}" style="display:inline-block;vertical-align:middle;margin-right:4px;"></div> ${p.v}</td>
            </tr>`;
            if (p.dia) html += `<tr style="background:#f9f9f9;"><td colspan="3" style="text-align:center;font-size:9px;color:#999;padding:2px;">📅 ${p.dia}</td></tr>`;
        }
    });
    html += `</table>`;
    } // cierre else (fecha con datos)

    // Tabla de posiciones — solo puntos, calculados desde fixtures
    const BD_RESERVA_POS = {
        'oficial':    [
                       {n:"Bella Vista",   cl:"bellavista",   pj:4, pg:3, pe:1, pp:0, gf:7, gc:4, pts:10},
                       {n:"Sporting <b>(A)</b>",      cl:"sporting",     pj:4, pg:2, pe:2, pp:0, gf:7, gc:5, pts:8},
                       {n:"Villa Mitre",   cl:"villamitre",   pj:4, pg:2, pe:1, pp:1, gf:8, gc:10, pts:7},
                       {n:"La Armonía",    cl:"laarmonia",    pj:4, pg:1, pe:2, pp:1, gf:6, gc:6, pts:5},
                       {n:"Liniers",       cl:"liniers",      pj:4, pg:2, pe:0, pp:2, gf:4, gc:2, pts:3},
                       {n:"Libertad",      cl:"libertad",     pj:4, pg:1, pe:0, pp:3, gf:6, gc:6, pts:3},
                       {n:"San Francisco", cl:"sanfrancisco", pj:4, pg:1, pe:10, pp:2, gf:6, gc:7, pts:4},
                       {n:"Huracán",       cl:"huracan",      pj:4, pg:0, pe:1, pp:3, gf:8, gc:13, pts:1}],
        'promocional':[
                       {n:"Olimpo <b>(A)</b>",              cl:"olimpo",           pj:3, pg:3, pe:0, pp:0, gf:8, gc:3, pts:9},
                       {n:"Sansinena",           cl:"sansinena",        pj:3, pg:2, pe:0, pp:1, gf:9, gc:4, pts:6},
                       {n:"Rosario PB",          cl:"rosariopb",        pj:4, pg:2, pe:0, pp:2, gf:8, gc:9, pts:6},
                       {n:"Tiro Federal",        cl:"tirofederal",      pj:3, pg:2, pe:0, pp:1, gf:8, gc:3, pts:6},
                       {n:"Pacífico BB",         cl:"pacificobb",       pj:3, pg:2, pe:0, pp:1, gf:2, gc:2, pts:6},
                       {n:"Dublin",              cl:"dublin",           pj:3, pg:1, pe:1, pp:1, gf:8, gc:8, pts:4},
                       {n:"Pacífico (C)", cl:"pacificocabildo",  pj:4, pg:0, pe:1, pp:3, gf:6, gc:15, pts:1},
                       {n:"Comercial",           cl:"comercial",        pj:3, pg:0, pe:0, pp:3, gf:2, gc:7, pts:0},],
        'segundafemenino': [
            {n:"Liniers <b>(C)</b>",             cl:"liniers",         pj:14, pg:12, pe:2, pp:0, gf:56, gc:10, pts:38},
            {n:"San Francisco",       cl:"sanfrancisco",    pj:13, pg:9, pe:2, pp:2, gf:29, gc:13, pts:29},
            {n:"Rosario PB",          cl:"rosariopb",       pj:13, pg:8, pe:2, pp:3, gf:27, gc:17, pts:26},
            {n:"Estrella de Oro",     cl:"estrellaoro",     pj:15, pg:7, pe:2, pp:6, gf:24, gc:21, pts:23},
            {n:"<s>Huracán</s> <b>(-)</b>",             cl:"huracan",         pj:11, pg:2, pe:0, pp:9, gf:6, gc:19, pts:6},
            {n:"Petroquímicos",       cl:"petroquimicos",   pj:12, pg:1, pe:1, pp:10, gf:10, gc:24, pts:4},
            {n:"<s>Sansinena</s> <b>(-)</b>",           cl:"sansinena",       pj:12, pg:1, pe:1, pp:10, gf:8, gc:55, pts:4}
        ],
        'femenino':   [
            {n:"Bella Vista",           cl:"bellavista", pj:5,pg:5, pe:0, pp:0, gf:11, gc:0, pts:15},
            {n:"Tiro Federal <b>(A)</b>",          cl:"tirofederal",pj:5,pg:4, pe:1, pp:0, gf:3, gc:1, pts:13},
            {n:"Villa Mitre",           cl:"villamitre", pj:5,pg:4, pe:0, pp:1, gf:6, gc:2, pts:12},
            {n:"Libertad",              cl:"libertad",   pj:5,pg:2, pe:0, pp:3, gf:1, gc:18, pts:6},
            {n:"Municipales",           cl:"municipales",pj:5,pg:1, pe:2, pp:2, gf:11, gc:5, pts:5},
            {n:"Sporting",              cl:"sporting",  pj:5,pg:1, pe:1, pp:3, gf:1, gc:7, pts:4},
            {n:"<s>Empleados de Comercio</s> <b>(-)</b>", cl:"empleados", pj:0,pg:0, pe:0, pp:0, gf:0, gc:0, pts:0},
            {n:"<s>La Armonía</s> <b>(-)</b>",            cl:"laarmonia",  pj:0,pg:0, pe:0, pp:0, gf:0, gc:0, pts:0}
        ]
    };

    const posManual = BD_RESERVA_POS[cat];
    if (posManual) {
        const tienePJ = posManual[0].pj !== undefined;
        html += `<div class="header-t">POSICIONES — RESERVA ${catLabel}</div>
        <table><thead><tr>
            <th style="width:25px;">#</th>
            <th style="text-align:left;padding-left:8px;">Equipo</th>
            ${tienePJ ? '<th class="c-stat">PJ</th><th class="c-stat">PG</th><th class="c-stat">PE</th><th class="c-stat">PP</th><th class="c-stat">GF</th><th class="c-stat">GC</th><th class="c-stat">Dif</th>' : ''}
            <th class="c-stat">Pts</th>
        </tr></thead><tbody>`;
        posManual.forEach((e, i) => {
            const cl = i < 4 ? 'p-playoff' : '';
            const dif = tienePJ ? (e.gf - e.gc) : 0;
            html += `<tr class="${cl}">
                <td class="c-pos">${i+1}</td>
                <td class="c-equipo">${e.n}</td>
                ${tienePJ ? `<td class="c-stat">${e.pj}</td><td class="c-stat">${e.pg}</td><td class="c-stat">${e.pe}</td><td class="c-stat">${e.pp}</td><td class="c-stat">${e.gf}</td><td class="c-stat">${e.gc}</td><td class="c-stat">${dif > 0 ? '+'+dif : dif}</td>` : ''}
                <td class="c-stat"><b>${e.pts}</b></td>
            </tr>`;
        });
        html += `</tbody></table>`;
        if (cat === 'oficial') {
            html += `<div style='background:#f9f9f9; padding:4px 8px; font-size:10px; text-align:center; color:#555;'><b>(A)</b> Ganador del Apertura<br>📌 Puntos en juego: <b>33</b> tras la fecha 3</div>`;
        } else if (cat === 'promocional') {
            html += `<div style='background:#f9f9f9; padding:4px 8px; font-size:10px; text-align:center; color:#555;'><b>(A)</b> Ganador del Apertura<br>📌 Puntos en juego: <b>30</b> tras la fecha 4</div>`;
        } else if (cat === 'femenino') {
            html += `<div style='background:#f9f9f9; padding:4px 8px; font-size:10px; text-align:center; color:#555;'><b>(A)</b> Campeón del Apertura<br><b>(-)</b> No presenta reserva<br>📌 Puntos en juego: <b>33</b> tras la fecha 3</div>`;
        } else if (cat === 'segundafemenino') {
html += `<div style='background:#f9f9f9; padding:4px 8px; font-size:10px; text-align:center; color:#555;'><b>(C) Clasificado</b><br><b>(-) No presenta reserva</b><br>📌 Puntos en juego: <b>-</b><br></div>`;
        }
    }
    return html;
}


