function generarSub15Fem() {
    const equipos = BD_EQUIPOS.sub15fem;
    const n = estado.fecha || 1;
    const f = idaSub15Fem.find(x => x.fecha === n) || { partidos: [] };

    let html = `<div class="nav-fechas">`;
    for (let i = 1; i <= 22; i++) {
        html += `<div class="btn-f ${i === n ? 'activa' : ''}" onclick="cambiarFecha(${i})">${i}</div>`;
    }
    html += `</div>`;
    html += `<div class="header-t">SUB 15 FEMENINO 2026 — FECHA ${n}</div><table>`;
    f.partidos.forEach(p => {
        const escL = equipos.find(e => e.nombre === p.l)?.clase || '';
        const escV = equipos.find(e => e.nombre === p.v)?.clase || '';
        const res = p.gl !== null ? `${p.gl} - ${p.gv}` : '- -';
        html += `<tr>
            <td class="c-loc"><span style="direction:ltr;display:inline-flex;align-items:center;justify-content:flex-end;width:100%;">${p.l} <div class="escudo ${escL}" style="display:inline-block;vertical-align:middle;margin-left:4px;"></div></span></td>
            <td class="c-res">${res}</td>
            <td class="c-vis"><div class="escudo ${escV}" style="display:inline-block;vertical-align:middle;margin-right:4px;"></div> ${p.v}</td>
        </tr>`;
    });
    html += `</table>`;

    // Posiciones calculadas desde el fixture
    const statsS15F = BD_EQUIPOS.sub15fem.map(e => ({...e, pj:0, pg:0, pe:0, pp:0, gf:0, gc:0, pts:0}));
    idaSub15Fem.flatMap(f => f.partidos).forEach(p => {
        if (p.gl !== null && p.gl !== undefined) {
            const l = statsS15F.find(x => x.nombre === p.l);
            const v = statsS15F.find(x => x.nombre === p.v);
            if (!l || !v) return;
            l.pj++; v.pj++; l.gf += p.gl; l.gc += p.gv; v.gf += p.gv; v.gc += p.gl;
            if (p.gl > p.gv)      { l.pg++; l.pts += 3; v.pp++; }
            else if (p.gv > p.gl) { v.pg++; v.pts += 3; l.pp++; }
            else                  { l.pe++; v.pe++; l.pts++; v.pts++; }
        }
    });
    statsS15F.sort((a,b) => b.pts - a.pts || (b.gf-b.gc) - (a.gf-a.gc));
    html += `<div class="header-t">POSICIONES — SUB 15 FEMENINO</div>
    <table><thead><tr>
        <th style="width:25px;">#</th>
        <th style="text-align:left;padding-left:8px;">Equipo</th>
        <th class="c-stat">PJ</th><th class="c-stat">PG</th><th class="c-stat">PE</th>
        <th class="c-stat">PP</th><th class="c-stat">GF</th><th class="c-stat">GC</th>
        <th class="c-stat">Dif</th><th class="c-stat">Pts</th>
    </tr></thead><tbody>`;
    statsS15F.forEach((e, i) => {
        html += `<tr>
            <td class="c-pos">${i+1}</td>
            <td class="c-equipo"><div class="escudo ${e.clase}" style="display:inline-block;vertical-align:middle;margin-right:4px;"></div>${e.nombre}</td>
            <td class="c-stat">${e.pj}</td><td class="c-stat">${e.pg}</td><td class="c-stat">${e.pe}</td>
            <td class="c-stat">${e.pp}</td><td class="c-stat">${e.gf}</td><td class="c-stat">${e.gc}</td>
            <td class="c-stat">${e.gf-e.gc}</td><td class="c-stat"><b>${e.pts}</b></td>
        </tr>`;
    });
    html += `</tbody></table>`;
    html += `<div style='background:#f9f9f9; padding:4px 8px; font-size:10px; text-align:center; color:#555;'>📌 Puntos en juego: <b>18</b> tras la finalización de la fecha <b>16</b></div>`;
    return html;
}

function generarFutsal(modo) {
    modo = modo || 'principal';
    const equipos = BD_EQUIPOS.futsal;
    const fixtures = modo === 'reserva' ? BD_FIXTURES_FUTSAL_RESERVA : BD_FIXTURES_FUTSAL;
    const n = estado.fecha || 1;
    const f = fixtures.find(x => x.fecha === n) || { partidos: [] };
    const titulo = modo === 'reserva' ? 'FUTSAL 2026 - RESERVA' : 'FUTSAL 2026';

    const navDest = modo === 'reserva' ? 'futsalreservaplayoffs' : 'futsalplayoffs';
    let html = `<div onclick="navegar('${navDest}')" style="background:linear-gradient(135deg,#7b1a1a,#a93226);color:#fff;text-align:center;padding:9px 12px;font-size:12px;font-weight:bold;letter-spacing:0.5px;cursor:pointer;border-bottom:2px solid #f0a500;">🏆 Ver cuadro de Playoffs del Apertura ▶</div>`;
    html += `<div class="nav-fechas">`;
    for (let i = 1; i <= 13; i++) {
        html += `<div class="btn-f ${i === n ? 'activa' : ''}" onclick="estado.fecha=${i};document.getElementById('contenido').innerHTML=generarFutsal('${modo}')">${i}</div>`;
    }
    html += `</div>`;
    html += `<div class="header-t">${titulo} - FECHA ${n}</div><table>`;
    f.partidos.forEach(p => {
        const escL = equipos.find(e => e.nombre === p.l)?.clase || '';
        const escV = equipos.find(e => e.nombre === p.v)?.clase || '';
        if (p.gl === null) {
            html += `<tr>
                <td class="c-loc"><span style="direction:ltr;display:inline-flex;align-items:center;justify-content:flex-end;width:100%;">${p.l} <div class="escudo ${escL}" style="display:inline-block;vertical-align:middle;margin-left:4px;"></div></span></td>
                <td class="c-res" style="font-size:10px;color:#888;">${p.dia ? p.dia+'<br>'+p.hora : '- -'}</td>
                <td class="c-vis"><div class="escudo ${escV}" style="display:inline-block;vertical-align:middle;margin-right:4px;"></div> ${p.v}</td>
            </tr>`;
        } else {
            html += `<tr>
                <td class="c-loc"><span style="direction:ltr;display:inline-flex;align-items:center;justify-content:flex-end;width:100%;">${p.l} <div class="escudo ${escL}" style="display:inline-block;vertical-align:middle;margin-left:4px;"></div></span></td>
                <td class="c-res">${p.gl} - ${p.gv}</td>
                <td class="c-vis"><div class="escudo ${escV}" style="display:inline-block;vertical-align:middle;margin-right:4px;"></div> ${p.v}</td>
            </tr>`;
if ((p.goles_l && p.goles_l.length) || (p.goles_v && p.goles_v.length)) {
    html += `<tr>
        <td colspan="3" style="font-size:9px;color:#666;padding:2px 8px;font-style:italic;">
            ${p.goles_l?.length > 0 ? `⚽${p.l}: ${p.goles_l.join(", ")}` : ""}
            ${(p.goles_l?.length > 0 && p.goles_v?.length > 0) ? " | " : ""}
            ${p.goles_v?.length > 0 ? `⚽${p.v}: ${p.goles_v.join(", ")}` : ""}
        </td>
    </tr>`;
}
        }

    });
    html += `</table>`;

    // Posiciones manuales
    const posData = BD_POS_FUTSAL[modo] || [];
    html += `<div class="header-t">POSICIONES - ${titulo}</div>
    <table><thead><tr>
        <th style="width:25px;">#</th>
        <th style="text-align:left;padding-left:8px;">Equipo</th>
        <th class="c-stat">PJ</th><th class="c-stat">PG</th><th class="c-stat">PE</th>
        <th class="c-stat">PP</th><th class="c-stat">GF</th><th class="c-stat">GC</th>
        <th class="c-stat">Dif</th><th class="c-stat">Pts</th>
    </tr></thead><tbody>`;
    posData.forEach((e, i) => {
        const dif = e.gf - e.gc;
        const clFila = i < 8 ? 'p-playoff' : '';
        html += `<tr class="${clFila}">
            <td class="c-pos">${i+1}</td>
            <td class="c-equipo"><div class="escudo ${e.cl}" style="display:inline-block;vertical-align:middle;margin-right:4px;"></div>${e.n}</td>
            <td class="c-stat">${e.pj}</td><td class="c-stat">${e.pg}</td><td class="c-stat">${e.pe}</td>
            <td class="c-stat">${e.pp}</td><td class="c-stat">${e.gf}</td><td class="c-stat">${e.gc}</td>
            <td class="c-stat">${dif > 0 ? '+'+dif : dif}</td><td class="c-stat"><b>${e.pts}</b></td>
        </tr>`;
    });
    html += `</tbody></table>`;
    if (modo === 'principal') {
html += `<div style='background:#f9f9f9; padding:4px 8px; font-size:10px; text-align:center; color:#555;'><b>📌 Puntos en juego:</b> 33 tras terminar la fecha 2<br><b>(A)</b> Campeón del Apertura<br><b>(-)</b> Se bajó de la competencia para el Clausura</div>`;
    } else if (modo === 'reserva') {
        html += `<div style='background:#f9f9f9; padding:4px 8px; font-size:10px; text-align:center; color:#555;'><b>📌 Puntos en juego:</b> 33 tras terminar la fecha 2<br><b>(A)</b> Campeón del Apertura<br><b>(-)</b> Se bajó de la competencia para el Clausura</div>`;
    }
    return html;
}

