function generarSeniorApertura() {
    const n = estado.fechaSenior || 9;
    const f = BD_FIXTURES_SENIOR.find(x => x.fecha === n) || { partidos: [], libre: null };
    const equipos = BD_SENIOR_APERTURA.map(e => ({ nombre: e.n, clase: e.cl }));

    // Visera playoffs
    let html = `<div onclick="navegar('seniorplayoffs')" style="background:linear-gradient(135deg,#7b1a1a,#a93226);color:#fff;text-align:center;padding:9px 12px;font-size:12px;font-weight:bold;letter-spacing:0.5px;cursor:pointer;border-bottom:2px solid #f0a500;">🏆 Ver cuadro de Playoffs del Apertura ▶</div>`;

    // Nav fechas
    html += `<div class="nav-fechas">`;
    for (let i = 1; i <= 9; i++) {
        const tieneDatos = BD_FIXTURES_SENIOR.find(x => x.fecha === i)?.partidos.length > 0;
        html += `<div class="btn-f ${i === n ? 'activa' : ''}" onclick="estado.fechaSenior=${i};document.getElementById('contenido').innerHTML=generarSeniorApertura()" style="${tieneDatos ? '' : 'color:#bbb;'}">${i}</div>`;
    }
    html += `</div>`;

    // Fixture
    html += `<div class="header-t">SENIOR — APERTURA 2026 — FECHA ${n}</div>`;
    if (f.libre) html += `<div style="padding:5px 10px; font-size:11px; background:#f9f9f9; border-bottom:1px solid #eee;"><b>Fecha libre:</b> ${f.libre}</div>`;
    if (f.partidos.length === 0) {
        html += `<div class="msg-prox">Sin datos para esta fecha</div>`;
    } else {
        html += `<table>`;
        f.partidos.forEach(p => {
            const escL = equipos.find(e => e.nombre === p.l)?.clase || '';
            const escV = equipos.find(e => e.nombre === p.v)?.clase || '';
            if (p.gl === null) {
                html += `<tr>
                    <td class="c-loc"><span style="direction:ltr;display:inline-flex;align-items:center;justify-content:flex-end;width:100%;">${p.l} <div class="escudo ${escL}" style="display:inline-block;vertical-align:middle;margin-left:4px;"></div></span></td>
                    <td class="c-res" style="font-size:10px;color:#888;">${f.dia ? f.dia + (p.hora ? '<br>' + p.hora : '') : '- -'}</td>
                    <td class="c-vis"><div class="escudo ${escV}" style="display:inline-block;vertical-align:middle;margin-right:4px;"></div> ${p.v}</td>
                </tr>`;
} else {
                html += `<tr>
                    <td class="c-loc"><span style="direction:ltr;display:inline-flex;align-items:center;justify-content:flex-end;width:100%;">${p.l} <div class="escudo ${escL}" style="display:inline-block;vertical-align:middle;margin-left:4px;"></div></span></td>
                    <td class="c-res">${p.gl} - ${p.gv}</td>
                    <td class="c-vis"><div class="escudo ${escV}" style="display:inline-block;vertical-align:middle;margin-right:4px;"></div> ${p.v}</td>
                </tr>`;
                if ((p.goles_l && p.goles_l.length) || (p.goles_v && p.goles_v.length)) {
                    html += `<tr style="background:#f7f7f7;"><td colspan="3" style="font-size:9px;color:#666;padding:2px 8px 3px;font-style:italic;">`;
                    if (p.goles_l?.length) html += `⚽ ${p.l}: ${p.goles_l.join(", ")}`;
                    if (p.goles_l?.length && p.goles_v?.length) html += ` &nbsp;|&nbsp; `;
                    if (p.goles_v?.length) html += `⚽ ${p.v}: ${p.goles_v.join(", ")}`;
                    html += `</td></tr>`;
                }
            }
        });
        html += `</table>`;
    }

    // Posiciones
    html += `<div class="header-t">POSICIONES — SENIOR APERTURA 2026</div>`;
    html += `<table><thead><tr>
        <th style="width:25px;">#</th>
        <th style="text-align:left;padding-left:8px;">Equipo</th>
        <th class="c-stat">PJ</th><th class="c-stat">PG</th><th class="c-stat">PE</th>
        <th class="c-stat">PP</th><th class="c-stat">GF</th><th class="c-stat">GC</th>
        <th class="c-stat">Dif</th><th class="c-stat">Pts</th>
    </tr></thead><tbody>`;
    BD_SENIOR_APERTURA.forEach((e, i) => {
        const dif = e.gf - e.gc;
        const cl = i < 2 ? 'p-playoff' : 'p-desc';
        html += `<tr class="${cl}" ${i === 0 ? 'style="background:#0af725;"' : ''}>
            <td class="c-pos">${i+1}</td>
            <td class="c-equipo"><div class="escudo ${e.cl}" style="display:inline-block;vertical-align:middle;margin-right:4px;"></div>${e.n}${e.n === 'Huracán' ? ' *' : ''}</td>
            <td class="c-stat">${e.pj}</td><td class="c-stat">${e.pg}</td><td class="c-stat">${e.pe}</td>
            <td class="c-stat">${e.pp}</td><td class="c-stat">${e.gf}</td><td class="c-stat">${e.gc}</td>
            <td class="c-stat">${dif > 0 ? '+'+dif : dif}</td><td class="c-stat"><b>${e.pts}</b></td>
        </tr>`;
    });
    html += `</tbody></table>`;
    html += `<div style="background:#f9f9f9; padding:6px 10px; font-size:10px; border-bottom:1px solid #eee;">
    <span style="display:inline-block;width:12px;height:12px;background:#4CAF50;border-radius:2px;vertical-align:middle;margin-right:4px;"></span> Clasifican a <b>semifinales</b><br>
    <span style="display:inline-block;width:12px;height:12px;background:#e74c3c;border-radius:2px;vertical-align:middle;margin-right:4px;margin-top:3px;"></span> Clasifican a <b>octavos de final</b>
</div>`;
    html += `<div style='background:#f9f9f9; padding:4px 8px; font-size:10px; text-align:center; color:#555;'>📌 Puntos en juego: <b>Torneo finalizado<br>*A Comercial se le descontaron 3 puntos por mala inclusión vs. Libertad</div>`;
    return html;
}

