function generarH2H(eq1, eq2, cls1, cls2, catKey) {
    // Buscar clave en BD_H2H (orden canónico: el que fue clickeado primero es eq1)
    const clave1 = `${eq1}|${eq2}`;
    const clave2 = `${eq2}|${eq1}`;
    const todosH2H = BD_H2H[clave1] || BD_H2H[clave2] || [];
    const normalizarCat = cat => cat === 'seniorapertura' || cat === 'seniorclausura' ? 'senior' : cat;
    const partidos = catKey ? todosH2H.filter(p => normalizarCat(p.torneo) === normalizarCat(catKey)) : todosH2H;

    // Combinar todos los partidos (BD_H2H + fixtures)
    const todos = [...partidos];

    // Calcular stats desde perspectiva de eq1
    let gano1 = 0, gano2 = 0, empates = 0, goles1 = 0, goles2 = 0;
    todos.forEach(p => {
        const eq1Local = p.l === eq1;
        const g1 = eq1Local ? (p.gl ?? 0) : (p.gv ?? 0);
        const g2 = eq1Local ? (p.gv ?? 0) : (p.gl ?? 0);
        goles1 += g1;
        goles2 += g2;
        if (g1 > g2) gano1++;
        else if (g2 > g1) gano2++;
        else empates++;
    });
    const esOlimpoVsVillaMitreFederal = catKey === 'federala' &&
        ((eq1 === 'Olimpo' && eq2 === 'Villa Mitre') || (eq1 === 'Villa Mitre' && eq2 === 'Olimpo'));
    let anioDesde = 2026;
    if (esOlimpoVsVillaMitreFederal) {
        const aniosEncontrados = todos.map(p => {
            const matches = (p.fecha || '').match(/\d{4}/g);
            return matches ? Math.min(...matches.map(Number)) : null;
        }).filter(a => a !== null);
        if (aniosEncontrados.length > 0) anioDesde = Math.min(...aniosEncontrados);
    }

    const diff = gano1 - gano2;
    let ventajaStr = '';
    if (diff > 0) ventajaStr = `<b>${eq1}</b> lleva una ventaja de ${diff} partido${diff>1?'s':''} sobre ${eq2} desde ${anioDesde}`;
    else if (diff < 0) ventajaStr = `<b>${eq2}</b> lleva una ventaja de ${Math.abs(diff)} partido${Math.abs(diff)>1?'s':''} sobre ${eq1} desde ${anioDesde}`;
    else if (todos.length > 0) ventajaStr = `Están igualados desde ${anioDesde}`;
    else ventajaStr = `Aún no se enfrentaron desde ${anioDesde}`;

    const esc1 = `<div class="escudo ${cls1}" style="display:inline-block;vertical-align:middle;margin-right:4px;"></div>`;
    const esc2 = `<div class="escudo ${cls2}" style="display:inline-block;vertical-align:middle;margin-right:4px;"></div>`;

    let html = `
    <div style="display:flex;align-items:center;gap:8px;padding:8px 10px;background:#f5f5f5;border-bottom:1px solid #ddd;cursor:pointer;" onclick="navegar('historial')">
        <span style="font-size:16px;color:#00331a;">←</span>
        <span style="font-size:11px;color:#555;">Volver al Historial</span>
    </div>
    <div class="header-t" style="display:flex;align-items:center;gap:8px;justify-content:center;">
        <div class="escudo ${cls1}"></div>
        ${eq1} vs ${eq2}
        <div class="escudo ${cls2}"></div>
    </div>
    <div style="background:#f0f7f0;border:1px solid #c8e6c9;border-radius:6px;padding:12px 16px;margin:10px 8px;font-size:12px;line-height:2;">
        ${esc1} <b>${eq1}</b> ganó <b>${gano1}</b> partido${gano1!==1?'s':''} desde ${anioDesde} y anotó <b>${goles1}</b> gol${goles1!==1?'es':''}.<br>
        ${esc2} <b>${eq2}</b> ganó <b>${gano2}</b> partido${gano2!==1?'s':''} desde ${anioDesde} y anotó <b>${goles2}</b> gol${goles2!==1?'es':''}.<br>
        Empataron <b>${empates}</b> ${empates!==1?'veces':'vez'} desde ${anioDesde}.<br>
        <span style="font-weight:bold;color:#00331a;">${ventajaStr}</span>
    </div>`;

    if (todos.length === 0) {
        html += `<div style="text-align:center;padding:20px;color:#999;font-size:12px;">Aún no se enfrentaron desde ${anioDesde}</div>`;
    } else {
        html += `<div class="header-t">PARTIDOS</div><table>`;
        todos.forEach(p => {
const catBase = {'reserva_oficial':'oficial','reserva_promocional':'promocional','reserva_femenino':'femenino','reserva_segundafemenino':'segundafemenino','futsalreserva':'futsal','seniorapertura':'seniorapertura','copaargentina':'copaargentina'}[p.torneo] || p.torneo || catKey || '';
const equiposLookup = catBase === 'seniorapertura'
    ? BD_SENIOR_APERTURA.map(e => ({ nombre: e.n, clase: e.cl }))
    : (BD_EQUIPOS[catBase] || BD_EQUIPOS[catKey] || []);
const escL = equiposLookup.find(e=>e.nombre===p.l)?.clase || Object.values(BD_EQUIPOS).flat().find(e=>e.nombre===p.l)?.clase || '';
const escV = equiposLookup.find(e=>e.nombre===p.v)?.clase || Object.values(BD_EQUIPOS).flat().find(e=>e.nombre===p.v)?.clase || '';
            html += `<tr>
                <td style="width:52px;background:#f0f0f0;border-right:1px solid #ddd;text-align:center;font-size:9px;color:#666;padding:3px;">${p.fecha||''}</td>
                <td class="c-loc"><span style="direction:ltr;display:inline-flex;align-items:center;justify-content:flex-end;width:100%;">${p.l} <div class="escudo ${escL}" style="margin-left:4px;"></div></span></td>
                <td class="c-res">${p.gl} - ${p.gv}${(p.pen_l !== null && p.pen_l !== undefined) ? ' ('+p.pen_l+'-'+p.pen_v+' pen.)' : ''}</td>
                <td class="c-vis"><div class="escudo ${escV}"></div> ${p.v}</td>
                <td style="width:52px;"></td>
            </tr>`;
            if ((p.goles_l?.length) || (p.goles_v?.length)) {
                const gl = (p.goles_l||[]).join(', ');
                const gv = (p.goles_v||[]).join(', ');
                html += `<tr style="background:#f7f7f7;"><td colspan="5" style="font-size:9px;color:#666;padding:2px 8px 3px;font-style:italic;">`;
                if (gl) html += `⚽ ${p.l}: ${gl}`;
                if (gl && gv) html += ` &nbsp;|&nbsp; `;
                if (gv) html += `⚽ ${p.v}: ${gv}`;
                html += `</td></tr>`;
            }
        });
        html += `</table>`;
    }

    return html;
}

function generarEquiposFuera() {
    const equiposOrden = [];
    const grupos = {};
    BD_EQUIPOS_FUERA.forEach(d => {
        if (!grupos[d.equipo]) { grupos[d.equipo] = { clase: d.clase, registros: [] }; equiposOrden.push(d.equipo); }
        grupos[d.equipo].registros.push(d);
    });
    equiposOrden.forEach(eq => {
        grupos[eq].registros.sort((a, b) => parseInt(String(a.anio).split('-')[0]) - parseInt(String(b.anio).split('-')[0]));
    });

    let html = `<div class="header-t">EQUIPOS DE LA LIGA DEL SUR EN TORNEOS SUPERIORES</div>`;
    html += `<style>
        .ef-accordion { margin-top:6px; }
        .ef-header { background:#00331a; color:#adff2f; font-size:11px; font-weight:bold; padding:7px 10px;
            display:flex; align-items:center; gap:6px; cursor:pointer; user-select:none;
            border-bottom:1px solid #005522; }
        .ef-header:hover { background:#004d20; }
        .ef-arrow { margin-left:auto; font-size:10px; transition:transform 0.2s; }
        .ef-arrow.open { transform:rotate(90deg); }
        .ef-body { display:none; }
        .ef-body.open { display:block; }
    </style>`;

    equiposOrden.forEach((equipo, idx) => {
        const g = grupos[equipo];
        const id = `ef_${idx}`;
        let filas = '';
        g.registros.forEach(d => {
            const clave = `${d.equipo}|${d.anio}|${d.torneo}`;
            const tieneDetalle = !!BD_DETALLES_FUERA[clave];
            const clicAttr = tieneDetalle ? `onclick="verDetalleTorneo('${clave.replace(/'/g, "\\'")}')" style="cursor:pointer;"` : "";
            const indicador = tieneDetalle ? ` <span style="color:#004d26; font-weight:bold; font-size:11px;">&#9654;</span>` : "";
            filas += `<tr ${clicAttr}>
                <td style="font-weight:bold;text-align:center;">${d.anio}</td>
                <td style="text-align:left;padding-left:8px;font-size:11px;">${d.torneo}${indicador}</td>
                <td style="text-align:left;padding-left:8px;font-size:11px;">${d.instancia}</td>
            </tr>`;
        });
        html += `
        <div class="ef-accordion">
            <div class="ef-header" onclick="toggleEfAccordion('${id}')">
                <div class="escudo ${g.clase}"></div>
                ${equipo.toUpperCase()}
                <span class="ef-arrow" id="arr_${id}">&#9654;</span>
            </div>
            <div class="ef-body" id="${id}">
                <table><thead><tr>
                    <th style="width:60px;">Año</th>
                    <th style="text-align:left;padding-left:8px;">Torneo</th>
                    <th style="text-align:left;padding-left:8px;">Puesto / Instancia a la que llegó</th>
                </tr></thead><tbody>${filas}</tbody></table>
            </div>
        </div>`;
    });

    html += `<div style="padding:8px;font-size:10px;text-align:center;color:#999;background:#f9f9f9;border-top:1px solid #eee;">Se incluyen torneos de AFA y otros torneos nacionales/regionales superiores a la Liga del Sur.</div>`;
    return html;
}

function toggleEfAccordion(id) {
    const body = document.getElementById(id);
    const arrow = document.getElementById('arr_' + id);
    const isOpen = body.classList.contains('open');
    // Cerrar todos
    document.querySelectorAll('.ef-body').forEach(el => el.classList.remove('open'));
    document.querySelectorAll('.ef-arrow').forEach(el => el.classList.remove('open'));
    // Abrir el clickeado si estaba cerrado
    if (!isOpen) {
        body.classList.add('open');
        arrow.classList.add('open');
    }
}

function verDetalleTorneo(clave) {
    const det = BD_DETALLES_FUERA[clave];
    if (!det) return;
    const partes = clave.split('|');
    const equipo = partes[0], anio = partes[1], torneo = partes[2];
    const claseEq = BD_EQUIPOS_FUERA.find(d => d.equipo === equipo && String(d.anio) === anio)?.clase || "";

    let html = `
        <div style="background:#004d26; padding:8px 10px; display:flex; align-items:center; gap:8px;">
            <button onclick="navegar('equiposfuera')" style="background:#adff2f; border:none; color:#004d26; font-weight:bold; font-size:11px; padding:5px 12px; cursor:pointer;">&#9664; VOLVER</button>
            <div style="color:white; font-size:13px; font-weight:bold; flex:1; text-align:center;">
                ${equipo.toUpperCase()} — ${torneo} (${anio})
            </div>
        </div>`;

    // Función auxiliar para renderizar tabla + partidos de una zona
    function renderZona(z) {
        let h = `<div class="header-t">${z.nombre.toUpperCase()}</div>`;
        if (z.solo_partidos) {
            h += `<table>`;
            z.partidos.forEach(p => {
                if (p.gl === null) {
                    h += `<tr style="background:#f0f0f0;"><td colspan="4" style="text-align:center;font-size:10px;color:#999;padding:4px;">— Fecha Libre —</td></tr>`;
                } else {
                    h += `<tr>
                        <td style="width:45px;background:#eee;text-align:center;font-size:10px;font-weight:bold;border-right:1px solid #ccc;">${p.condicion}${p.nota && p.nota.toLowerCase().includes('interzonal') ? '<br><span style=\"font-size:9px;font-weight:normal;color:#888;\">Interzonal</span>' : ''}</td>
                        <td class="c-loc">${p.local}</td>
                        <td class="c-res">${p.gl} - ${p.gv}</td>
                        <td class="c-vis">${p.visitante}</td>
                    </tr>`;
                    if (p.nota && !p.nota.toLowerCase().includes('interzonal')) h += `<tr style="background:#f5f5f5;"><td colspan="4" style="text-align:center;font-size:10px;color:#777;padding:3px 8px;font-style:italic;">📍 ${p.nota}</td></tr>`;
                }
            });
            h += `</table>`;
            return h;
        }
        if (z.es_promedio) {
            h += `<table><thead><tr>
                <th style="width:25px;">#</th>
                <th style="text-align:left;padding-left:8px;">Equipo</th>
                <th class="c-stat">Prom.</th>
            </tr></thead><tbody>`;
            z.equipos.forEach((e, i) => {
                let cl = e.clase_fila || "";
                const esNuestro = e.nombre === equipo;
                const estilo = esNuestro ? (cl ? "font-weight:bold;" : "font-weight:bold; background:white;") : "";
                h += `<tr class="${cl}" style="${estilo}">
                    <td class="c-pos">${i+1}</td>
                    <td class="c-equipo">${e.nombre}</td>
                    <td class="c-stat"><b>${e.promedio}</b></td>
                </tr>`;
            });
            h += `</tbody></table>`;
            return h;
        }
        if (z.puntos_y_dif) {
            h += `<table><thead><tr>
                <th style="width:25px;">#</th>
                <th style="text-align:left;padding-left:8px;">Equipo</th>
                <th class="c-stat">Pts</th>
                <th class="c-stat">Dif</th>
            </tr></thead><tbody>`;
            z.equipos.forEach((e, i) => {
                let cl = "";
                const total = z.equipos.length;
                const verde = z.clasificados || 0;
                const rojo  = z.clasificados_rojo || 0;
                if (i < verde) cl = "p-playoff";
                if (rojo > 0 && i >= total - rojo) cl = "p-desc";
                const esNuestro = e.nombre === equipo;
                const estilo = esNuestro ? (cl ? "font-weight:bold;" : "font-weight:bold; background:white;") : "";
                const dif = e.dif !== undefined ? e.dif : (e.gf - e.gc);
                const difStr = dif > 0 ? `+${dif}` : `${dif}`;
                h += `<tr class="${cl}" style="${estilo}">
                    <td class="c-pos">${i+1}</td>
                    <td class="c-equipo">${e.nombre}</td>
                    <td class="c-stat"><b>${e.pts}</b></td>
                    <td class="c-stat" style="font-size:10px;color:#666;">${difStr}</td>
                </tr>`;
            });
            h += `</tbody></table>`;
            if (z.nota_zona) h += `<div style="padding:8px 12px; font-size:11px; color:#444; background:#fff8e1; border-top:2px solid #ffd700; font-style:italic; text-align:center;">⚠️ ${z.nota_zona}</div>`;
            if (z.partidos) {
                h += `<div style="margin-top:10px;"></div><table>`;
                z.partidos.forEach(p => {
                    if (p.gl === null) {
                        h += `<tr style="background:#f0f0f0;"><td colspan="4" style="text-align:center;font-size:10px;color:#999;padding:4px;">— Fecha Libre —</td></tr>`;
                    } else {
                        h += `<tr>
                            <td style="width:45px;background:#eee;text-align:center;font-size:10px;font-weight:bold;border-right:1px solid #ccc;">${p.condicion}</td>
                            <td class="c-loc">${p.local}</td>
                            <td class="c-res">${p.gl} - ${p.gv}</td>
                            <td class="c-vis">${p.visitante}</td>
                        </tr>`;
                        if (p.nota) h += `<tr style="background:#f5f5f5;"><td colspan="4" style="text-align:center;font-size:10px;color:#777;padding:3px 8px;font-style:italic;">📍 ${p.nota}</td></tr>`;
                    }
                });
                h += `</table>`;
            }
            return h;
        }
        if (z.solo_puntos) {
            h += `<table><thead><tr>
                <th style="width:25px;">#</th>
                <th style="text-align:left;padding-left:8px;">Equipo</th>
                <th class="c-stat">Pts</th>
            </tr></thead><tbody>`;
            z.equipos.forEach((e, i) => {
                let cl = "";
                const total = z.equipos.length;
                const verde = z.clasificados || 0;
                const azul  = z.clasificados_secundarios_azul || 0;
                const amarillo = z.clasificados_secundarios || 0;
                const todosamarillo = z.clasificados_amarillo || 0;
                const rojo  = z.clasificados_rojo || 0;
                const promocion = z.clasificados_promocion || 0;
                if (todosamarillo > 0 && i < todosamarillo) cl = "p-mejorquinto";
                else if (amarillo > 0) { if (i === 0) cl = "p-playoff"; else if (i < amarillo) cl = "p-mejorquinto"; }
                else if (i < verde) cl = "p-playoff";
                if (azul > 0 && i >= verde && i < verde + azul) cl = "p-revalida";
                if (promocion > 0 && i >= total - rojo - promocion && i < total - rojo) cl = "p-promocion";
                if (rojo > 0 && i >= total - rojo) cl = "p-desc";
                // Colores por rango de posición
                const amarDesde    = z.clasificados_amarillo_desde;
                const amarHasta    = z.clasificados_amarillo_hasta;
                const azulPos      = z.clasificados_azul_pos;
                const naranjaDesde = z.clasificados_naranja_desde;
                const naranjaHasta = z.clasificados_naranja_hasta;
                const rojoResto    = z.clasificados_rojo_resto;
                const pos1 = i + 1;
                if (amarDesde && amarHasta && pos1 >= amarDesde && pos1 <= amarHasta) cl = "p-mejorquinto";
                if (azulPos && pos1 === azulPos) cl = "p-revalida";
                const azulLista = z.clasificados_azul_lista;
                const amarLista = z.clasificados_amarillo_lista;
                if (azulLista && azulLista.includes(pos1)) cl = "p-revalida";
                if (amarLista && amarLista.includes(pos1)) cl = "p-mejorquinto";
                if (naranjaDesde && naranjaHasta && pos1 >= naranjaDesde && pos1 <= naranjaHasta) cl = "p-naranja";
                if (rojoResto && (!amarDesde || pos1 < amarDesde || pos1 > amarHasta) && (!azulPos || pos1 !== azulPos) && (!naranjaDesde || pos1 < naranjaDesde || pos1 > naranjaHasta) && pos1 > verde) cl = "p-desc";
                const esNuestro = e.nombre === equipo;
                const estilo = esNuestro ? (cl ? "font-weight:bold;" : "font-weight:bold; background:white;") : "";
                h += `<tr class="${cl}" style="${estilo}">
                    <td class="c-pos">${i+1}</td>
                    <td class="c-equipo">${e.nombre}</td>
                    <td class="c-stat"><b>${e.pts}</b></td>
                </tr>`;
            });
            h += `</tbody></table>`;
            if (z.nota) h += `<div style="padding:6px 10px; font-size:10px; color:#555; background:#f9f9f9; border-top:1px solid #eee;">* ${z.nota}</div>`;
            if (z.nota_zona) h += `<div style="padding:8px 12px; font-size:11px; color:#444; background:#fff8e1; border-top:2px solid #ffd700; font-style:italic; text-align:center;">⚠️ ${z.nota_zona}</div>`;
            if (z.partidos) {
                h += `<div style="margin-top:10px;"></div><table>`;
                z.partidos.forEach(p => {
                    if (p.gl === null) {
                        h += `<tr style="background:#f0f0f0;"><td colspan="4" style="text-align:center;font-size:10px;color:#999;padding:4px;">— Fecha Libre —</td></tr>`;
                    } else {
                        h += `<tr>
                            <td style="width:45px;background:#eee;text-align:center;font-size:10px;font-weight:bold;border-right:1px solid #ccc;">${p.condicion}${p.nota && p.nota.toLowerCase().includes('interzonal') ? '<br><span style=\"font-size:9px;font-weight:normal;color:#888;\">Interzonal</span>' : ''}</td>
                            <td class="c-loc">${p.local}</td>
                            <td class="c-res">${p.gl} - ${p.gv}</td>
                            <td class="c-vis">${p.visitante}</td>
                        </tr>`;
                        const gl_loc2 = p.goles_local || [];
                        const gl_vis2 = p.goles_visitante || [];
                        if (gl_loc2.length > 0 || gl_vis2.length > 0) {
                            const textoLoc2 = gl_loc2.length > 0 ? `⚽ ${gl_loc2.join(" · ")}` : "";
                            const textoVis2 = gl_vis2.length > 0 ? `⚽ ${gl_vis2.join(" · ")}` : "";
                            h += `<tr style="background:#f0f0f0;">
                                <td></td>
                                <td style="text-align:right;padding-right:6px;font-size:10px;color:#444;width:42%;">${textoLoc2}</td>
                                <td style="text-align:center;color:#bbb;font-size:12px;width:16%;">|</td>
                                <td style="text-align:left;padding-left:6px;font-size:10px;color:#444;width:42%;">${textoVis2}</td>
                            </tr>`;
                        }
                        if (p.nota && !p.nota.toLowerCase().includes('interzonal')) h += `<tr style="background:#f5f5f5;"><td colspan="4" style="text-align:center;font-size:10px;color:#777;padding:3px 8px;font-style:italic;">📍 ${p.nota}</td></tr>`;
                    }
                });
                h += `</table>`;
            }
            return h;
        }
        h += `<table><thead><tr>
            <th style="width:25px;">#</th>
            <th style="text-align:left;padding-left:8px;">Equipo</th>
            <th class="c-stat">PJ</th><th class="c-stat">PG</th><th class="c-stat">PE</th><th class="c-stat">PP</th>
            <th class="c-stat">GF</th><th class="c-stat">GC</th><th class="c-stat">Dif</th><th class="c-stat">Pts</th>
        </tr></thead><tbody>`;
        z.equipos.forEach((e, i) => {
            let cl = "";
            if (z.clasificados_secundarios && i === 0) cl = "p-playoff";
            else if (z.clasificados_secundarios && i < z.clasificados) cl = "p-mejorquinto";
            else if (z.clasificados_secundarios_azul && i === 0) cl = "p-playoff";
            else if (z.clasificados_secundarios_azul && i < (z.clasificados + z.clasificados_secundarios_azul)) cl = "p-revalida";
            else if (!z.clasificados_secundarios && !z.clasificados_secundarios_azul && i < z.clasificados) cl = "p-playoff";
            const esNuestro = e.nombre === equipo;
            const estilo = esNuestro ? (cl ? "font-weight:bold;" : "font-weight:bold; background:white;") : "";
            h += `<tr class="${cl}" style="${estilo}">
                <td class="c-pos">${i+1}</td>
                <td class="c-equipo">${e.nombre}</td>
                <td class="c-stat">${e.pj}</td><td class="c-stat">${e.pg}</td><td class="c-stat">${e.pe}</td><td class="c-stat">${e.pp}</td>
                <td class="c-stat">${e.gf}</td><td class="c-stat">${e.gc}</td><td class="c-stat">${e.gf - e.gc}</td>
                <td class="c-stat"><b>${e.pts}</b></td>
            </tr>`;
        });
        h += `</tbody></table>`;
        if (z.nota) {
            h += `<div style="padding:6px 10px; font-size:10px; color:#555; background:#f9f9f9; border-top:1px solid #eee;">* ${z.nota}</div>`;
        }
        if (z.partidos) {
            h += `<table>`;
            z.partidos.forEach(p => {
                if (p.gl === null) {
                    h += `<tr style="background:#f0f0f0;"><td colspan="4" style="text-align:center;font-size:10px;color:#999;padding:4px;">— Fecha Libre —</td></tr>`;
                } else {
                    h += `<tr>
                        <td style="width:45px;background:#eee;text-align:center;font-size:10px;font-weight:bold;border-right:1px solid #ccc;">${p.condicion}</td>
                        <td class="c-loc">${p.local}</td>
                        <td class="c-res">${p.gl} - ${p.gv}</td>
                        <td class="c-vis">${p.visitante}</td>
                    </tr>`;
                    const gl_loc = p.goles_local || [];
                    const gl_vis = p.goles_visitante || [];
                    if (gl_loc.length > 0 || gl_vis.length > 0) {
                        const textoLoc = gl_loc.length > 0 ? `⚽ ${gl_loc.join(" · ")}` : "";
                        const textoVis = gl_vis.length > 0 ? `⚽ ${gl_vis.join(" · ")}` : "";
                        h += `<tr style="background:#f0f0f0;">
                            <td></td>
                            <td style="text-align:right;padding-right:6px;font-size:10px;color:#444;width:42%;">${textoLoc}</td>
                            <td style="text-align:center;color:#bbb;font-size:12px;width:16%;">|</td>
                            <td style="text-align:left;padding-left:6px;font-size:10px;color:#444;width:42%;">${textoVis}</td>
                        </tr>`;
                    }
                    if (p.nota) {
                        h += `<tr style="background:#f5f5f5;"><td colspan="4" style="text-align:center;font-size:10px;color:#777;padding:3px 8px;font-style:italic;">📍 ${p.nota}</td></tr>`;
                    }
                }
            });
            h += `</table>`;
        }
        return h;
    }

    // DESCRIPCIÓN DEL TORNEO
    if (det.descripcion) {
        html += `<div style="background:#1a1a2e; border-left:4px solid #adff2f; color:#ccc; font-size:12px; line-height:1.6; padding:12px 14px; margin:10px 0; border-radius:4px;">${det.descripcion}</div>`;
    }

    // TABLA DE ZONA (singular)
    if (det.zona) { html += renderZona(det.zona); }

    // ZONAS MÚLTIPLES (plural, ej: Argentino B con varias rondas)
    if (det.zonas) { det.zonas.forEach(z => { html += renderZona(z); }); }

    // FASES ELIMINATORIAS
    if (det.fases) {
        det.fases.forEach(fase => {
            // Si la fase tiene zonas (tablas de grupo), usar renderZona
            if (fase.zonas) {
                html += `<div class="header-t">${fase.nombre.toUpperCase()}</div>`;
                fase.zonas.forEach(z => {
                    // Heredar campos de clasificación de la fase si la zona no los tiene
                    const zConClasif = {
                        ...z,
                        solo_puntos: z.solo_puntos ?? fase.solo_puntos,
                        puntos_y_dif: z.puntos_y_dif ?? fase.puntos_y_dif,
                        es_promedio: z.es_promedio ?? fase.es_promedio,
                        clasificados: z.clasificados ?? fase.clasificados,
                        clasificados_secundarios: z.clasificados_secundarios ?? fase.clasificados_secundarios,
                        clasificados_secundarios_azul: z.clasificados_secundarios_azul ?? fase.clasificados_secundarios_azul,
                        clasificados_amarillo: z.clasificados_amarillo ?? fase.clasificados_amarillo,
                        clasificados_rojo: z.clasificados_rojo ?? fase.clasificados_rojo,
                        clasificados_promocion: z.clasificados_promocion ?? fase.clasificados_promocion,
                        clasificados_azul_pos: z.clasificados_azul_pos ?? fase.clasificados_azul_pos,
                        clasificados_amarillo_desde: z.clasificados_amarillo_desde ?? fase.clasificados_amarillo_desde,
                        clasificados_amarillo_hasta: z.clasificados_amarillo_hasta ?? fase.clasificados_amarillo_hasta,
                        clasificados_naranja_desde: z.clasificados_naranja_desde ?? fase.clasificados_naranja_desde,
                        clasificados_naranja_hasta: z.clasificados_naranja_hasta ?? fase.clasificados_naranja_hasta,
                        clasificados_rojo_resto: z.clasificados_rojo_resto ?? fase.clasificados_rojo_resto,
                    };
                    html += renderZona(zConClasif);
                });
                // Mostrar nota de la fase después de las zonas
                if (fase.nota) {
                    const esEscandalo = fase.nota.toUpperCase().includes('ESCÁNDALO') || fase.nota.toUpperCase().includes('ESCANDALO');
                    if (esEscandalo) {
                        const partes = fase.nota.split(' — ');
                        const titulo = partes[0].replace('⚠️ ', '');
                        const texto = partes.slice(1).join(' — ');
                        html += `<div style="padding:10px 14px; background:#fff0f0; border-top:3px solid #c00; border-bottom:3px solid #c00; margin-top:4px;">
                            <div style="font-size:16px; font-weight:bold; color:#c00; text-align:center; text-transform:uppercase; letter-spacing:2px; margin-bottom:6px;">⚠️ ${titulo}</div>
                            <div style="font-size:11px; color:#444; text-align:center; font-style:italic;">${texto}</div>
                        </div>`;
                    } else {
                        html += `<div style="padding:8px 12px; font-size:11px; color:#444; background:#fff8e1; border-top:2px solid #ffd700; font-style:italic; text-align:center;">⚠️ ${fase.nota}</div>`;
                    }
                }
                return;
            }
            html += `<div class="header-t">${fase.nombre.toUpperCase()}</div><table>`;
            fase.partidos.forEach(p => {
                if (p.gl === null) {
                    html += `<tr style="background:#f0f0f0;">
                        <td style="width:45px;background:#eee;text-align:center;font-size:10px;font-weight:bold;border-right:1px solid #ccc;">${p.condicion}</td>
                        <td colspan="3" style="text-align:center;font-size:10px;color:#999;padding:4px;">— Fecha Libre —</td>
                    </tr>`;
                    return;
                }
                const claseL = p.local === equipo ? claseEq : "";
                const claseV = p.visitante === equipo ? claseEq : "";
                const filaStyle = p.esHistorico ? 'background:#fff3cd;' : '';
                html += `<tr style="${filaStyle}">
                    <td style="width:45px;background:#eee;text-align:center;font-size:10px;font-weight:bold;border-right:1px solid #ccc;">${p.condicion}</td>
                    <td class="c-loc">${p.local}</td>
                    <td class="c-res">${p.gl} - ${p.gv}</td>
                    <td class="c-vis">${p.visitante}</td>
                </tr>`;
                if (p.esHistorico) {
                    html += `<tr style="background:#fff8e1;">
                        <td colspan="4" style="font-size:10px; color:#7a5000; padding:5px 10px; text-align:center; font-style:italic;">
                            ⭐ Mayor goleada de la historia de Primera División del fútbol argentino. Juan Taverna marcó 7 goles, siendo el máximo goleador en un mismo partido en la historia del torneo.
                        </td>
                    </tr>`;
                }
                if (p.nota) {
                    html += `<tr style="background:#f5f5f5;"><td colspan="4" style="text-align:center;font-size:10px;color:#777;padding:3px 8px;font-style:italic;">📍 ${p.nota}</td></tr>`;
                }

                // Goles
                const gl_loc = p.goles_local || [];
                const gl_vis = p.goles_visitante || [];
                if (gl_loc.length > 0 || gl_vis.length > 0) {
                    const textoLoc = gl_loc.length > 0 ? `⚽ ${gl_loc.join(" · ")}` : "";
                    const textoVis = gl_vis.length > 0 ? `⚽ ${gl_vis.join(" · ")}` : "";
                    html += `<tr style="background:#f0f0f0;">
                        <td></td>
                        <td style="text-align:right;padding-right:6px;font-size:10px;color:#444;width:42%;">${textoLoc}</td>
                        <td style="text-align:center;color:#bbb;font-size:12px;width:16%;">|</td>
                        <td style="text-align:left;padding-left:6px;font-size:10px;color:#444;width:42%;">${textoVis}</td>
                    </tr>`;
                }

                // Penales
                if (p.penales) {
                    const pen = p.penales;
                    html += `<tr style="background:#e8f4fd;">
                        <td colspan="4" style="text-align:center;font-size:11px;font-weight:bold;padding:5px;color:#004d26;">
                            PENALES: ${p.local} ${pen.resultado} ${p.visitante} — Clasificó: <b>${pen.ganador}</b>
                        </td>
                    </tr>`;
                    if (pen.nota_extra) {
                        html += `<tr style="background:#e8f4fd;"><td colspan="4" style="text-align:center;font-size:10px;color:#555;padding:3px 8px;font-style:italic;">${pen.nota_extra}</td></tr>`;
                    }
                    if (pen.local_conv?.length || pen.local_fall?.length || pen.visitante_conv?.length || pen.visitante_fall?.length) {
                        html += `<tr style="background:#f0f8ff;"><td></td><td colspan="3" style="font-size:10px;padding:4px 8px;">`;
                        if (pen.local_conv?.length)     html += `<span style="color:green;">✔ Convirtieron (${p.local}): ${pen.local_conv.join(", ")}</span><br>`;
                        if (pen.local_fall?.length)     html += `<span style="color:#c00;">✘ Fallaron (${p.local}): ${pen.local_fall.join(", ")}</span><br>`;
                        if (pen.visitante_conv?.length) html += `<span style="color:green;">✔ Convirtieron (${p.visitante}): ${pen.visitante_conv.join(", ")}</span><br>`;
                        if (pen.visitante_fall?.length) html += `<span style="color:#c00;">✘ Fallaron (${p.visitante}): ${pen.visitante_fall.join(", ")}</span>`;
                        html += `</td></tr>`;
                    }
                }
            });
            html += `</table>`;
            if (fase.nota) {
                const esEscandalo = fase.nota.toUpperCase().includes('ESCÁNDALO') || fase.nota.toUpperCase().includes('ESCANDALO');
                if (esEscandalo) {
                    const partes = fase.nota.split(' — ');
                    const titulo = partes[0].replace('⚠️ ', '');
                    const texto = partes.slice(1).join(' — ');
                    html += `<div style="padding:10px 14px; background:#fff0f0; border-top:3px solid #c00; border-bottom:3px solid #c00; margin-top:4px;">
                        <div style="font-size:16px; font-weight:bold; color:#c00; text-align:center; text-transform:uppercase; letter-spacing:2px; margin-bottom:6px;">⚠️ ${titulo}</div>
                        <div style="font-size:11px; color:#444; text-align:center; font-style:italic;">${texto}</div>
                    </div>`;
                } else {
                    html += `<div style="padding:8px 12px; font-size:11px; color:#444; background:#fff8e1; border-top:2px solid #ffd700; font-style:italic; text-align:center;">⚠️ ${fase.nota}</div>`;
                }
            }
            if (fase.nota_ascenso) {
                html += `<div style="padding:10px 14px; background:#e8f5e9; border-top:3px solid #00331a; border-bottom:3px solid #00331a; margin-top:4px; text-align:center;">
                    <div style="font-size:15px; font-weight:bold; color:#00331a; text-transform:uppercase; letter-spacing:1px;">🏆 ${fase.nota_ascenso}</div>
                </div>`;
            }
        });
    }

    document.getElementById("contenido").innerHTML = html;
}

