function generarArqueros(cat, torneo) {
    torneo = torneo || 'apertura';
    const catLabel = cat === 'oficial' ? 'TORNEO OFICIAL' : cat === 'promocional' ? 'TORNEO PROMOCIONAL' : cat.toUpperCase();
    const fuenteClausura = cat === 'oficial' ? BD_ARQUEROS_CLAUSURA_OFICIAL : BD_ARQUEROS_CLAUSURA_PROMOCIONAL;

    const tabsHtml = `<div style="display:flex;gap:6px;padding:8px 8px 4px;background:#f9f9f9;border-bottom:1px solid #eee;">
        <button onclick="document.getElementById('contenido').innerHTML=generarArqueros('${cat}','apertura')"
            style="font-size:10px;padding:4px 12px;border:1px solid #1a4a2e;border-radius:12px;cursor:pointer;font-weight:bold;background:${torneo==='apertura'?'#1a4a2e':'#fff'};color:${torneo==='apertura'?'#fff':'#1a4a2e'};">Apertura</button>
        <button onclick="document.getElementById('contenido').innerHTML=generarArqueros('${cat}','clausura')"
            style="font-size:10px;padding:4px 12px;border:1px solid #1a4a2e;border-radius:12px;cursor:pointer;font-weight:bold;background:${torneo==='clausura'?'#1a4a2e':'#fff'};color:${torneo==='clausura'?'#fff':'#1a4a2e'};">Clausura</button>
        <button onclick="document.getElementById('contenido').innerHTML=generarArqueros('${cat}','total')"
            style="font-size:10px;padding:4px 12px;border:1px solid #1a4a2e;border-radius:12px;cursor:pointer;font-weight:bold;background:${torneo==='total'?'#1a4a2e':'#fff'};color:${torneo==='total'?'#fff':'#1a4a2e'};">Total</button>
    </div>`;

    let listaBase;
    if (torneo === 'clausura') {
        listaBase = fuenteClausura || [];
    } else if (torneo === 'total') {
        const combinados = {};
        (BD_ARQUEROS[cat] || []).forEach(a => {
            const key = `${a.jugador}|${a.equipo}`;
            if (!combinados[key]) combinados[key] = { jugador: a.jugador, equipo: a.equipo, partidos: [] };
            combinados[key].partidos.push(...a.partidos);
        });
        (fuenteClausura || []).forEach(a => {
            const key = `${a.jugador}|${a.equipo}`;
            if (!combinados[key]) combinados[key] = { jugador: a.jugador, equipo: a.equipo, partidos: [] };
            combinados[key].partidos.push(...a.partidos);
        });
        listaBase = Object.values(combinados);
    } else {
        listaBase = BD_ARQUEROS[cat] || [];
    }

    const lista = listaBase.slice().sort((a, b) => b.partidos.length - a.partidos.length || a.equipo.localeCompare(b.equipo) || a.jugador.localeCompare(b.jugador));

    if (lista.length === 0) return tabsHtml + `<div class="msg-prox">Sin datos registrados</div>`;

    let h = tabsHtml + `<div class="header-t">VALLAS INVICTAS — ${catLabel}</div><table>
    <thead><tr>
        <th style="width:25px;">#</th>
        <th style="text-align:left;padding-left:8px;">Arquero</th>
        <th style="text-align:left;padding-left:8px;">Equipo</th>
        <th class="c-stat">Vallas</th>
    </tr></thead><tbody>`;

    let pos = 1, prevVallas = -1, realIdx = 0;
    lista.forEach((g, i) => {
        realIdx++;
        if (g.partidos.length !== prevVallas) { pos = realIdx; prevVallas = g.partidos.length; }
        const escudo = BD_EQUIPOS[cat]?.find(e => e.nombre === g.equipo)?.clase || '';
        const rowId = `arq-${cat}-${torneo}-${i}`;
        h += `<tr style="cursor:pointer;" onclick="
            var d=document.getElementById('${rowId}');
            d.style.display = d.style.display==='none' ? 'table-row' : 'none';
        ">
            <td class="c-pos">${pos}</td>
            <td style="text-align:left;padding-left:8px;font-size:12px;font-weight:bold;color:#00331a;">${g.jugador} ▶</td>
            <td style="text-align:left;padding-left:8px;font-size:11px;"><div class="escudo ${escudo}" style="display:inline-block;vertical-align:middle;margin-right:4px;"></div>${g.equipo}</td>
            <td class="c-stat"><b>${g.partidos.length}</b></td>
        </tr>
        <tr id="${rowId}" style="display:none;background:#f0f7f0;">
            <td colspan="4" style="padding:6px 12px;">
                <div style="font-size:10px;font-weight:bold;color:#004d26;margin-bottom:4px;">PARTIDOS INVICTO:</div>
                ${g.partidos.map(p => `<div style="font-size:11px;padding:2px 0;border-bottom:1px solid #ddd;">📅 ${p.instancia ? p.instancia : 'Fecha ' + p.fecha} — ${p.resultado}</div>`).join('')}
            </td>
        </tr>`;
    });

    return h + '</tbody></table>';
}

function generarPerfilJugador(jugador, equipo, origen, totalOverride, catPerfil) {
    const cats = ['oficial', 'promocional', 'femenino', 'segundafemenino', 'federala'];
    const catLabels = { oficial: 'Torneo Oficial', promocional: 'Torneo Promocional', femenino: '1° Femenino', segundafemenino: '2° Femenino', federala: 'Federal A' };

    // Detectar si el jugador cambió de equipo en esta categoría
    let alias = null;
    for (const cat of cats) {
        const found = (BD_ALIAS_JUGADORES[cat] || []).find(a => a.nombre === jugador && a.equipos.includes(equipo));
        if (found) { alias = found; break; }
    }
    const equipoAnterior = alias ? alias.equipos[0] : null;
    const equipoActual   = alias ? alias.equipos[alias.equipos.length - 1] : equipo;
    const cambioDeEquipo = alias && alias.equipos.length > 1 && alias.equipos[0] !== alias.equipos[alias.equipos.length - 1] && (origen !== 'apertura' || !alias.desde);

    // Recolectar partidos etiquetados por equipo en que jugó
    const partidosPorEquipo = {}; // { nombreEquipo: [partidos] }

    cats.forEach(cat => {
        let fixtures;
        if (cat === 'segundafemenino') fixtures = BD_FIXTURES.segundafemenino.torneo2026;
        else if (cat === 'federala') fixtures = [...BD_FIXTURES.federala.posiciones, ...BD_FIXTURES.federala.nonagonal];
        else if (cat === 'oficial' || cat === 'promocional') fixtures = BD_FIXTURES[cat].apertura;
        else fixtures = BD_FIXTURES[cat]?.apertura || [];

        const todosPartidos = fixtures.flatMap(f => f.partidos);

        const playoffsBD = { oficial: BD_OFICIAL_PLAYOFFS, promocional: BD_PROMOCIONAL_PLAYOFFS, femenino: BD_FEMENINO_PLAYOFFS };
        const pd = playoffsBD[cat];
        if (pd) {
            [...(pd.octavos||[]), ...(pd.cuartos||[]), ...(pd.semifinales||[]), ...(pd.final?[pd.final]:[]), ...(pd.finalExtra?[pd.finalExtra]:[])]
                .filter(p => p && p.gl !== null)
                .forEach(p => { if (p) todosPartidos.push({ l: p.local, v: p.visitante, gl: p.gl, gv: p.gv, goles_l: p.goles_l||[], goles_v: p.goles_v||[], dia: 'Playoffs' }); });
        }

        let equiposBuscar;
if (alias) {
    equiposBuscar = alias.equipos;
} else {
    equiposBuscar = [equipo];
}
        const nombreLimpio = n => n.replace(' (e/c)', '').replace(' (p)', '').trim();
        const equiposBuscarFixture = (alias && alias.desde === 'clausura') ? [alias.equipos[0]] : equiposBuscar;

        todosPartidos.forEach(p => {
            if (p.gl === null) return;
            const golesL = p.goles_l || [];
            const golesV = p.goles_v || [];

            let golesJugador = 0, esEC = false, equipoEnEstePartido = null, condicion = null, rival = null;

            if (equiposBuscarFixture.includes(p.l)) {
                // Buscar goles normales en goles_l
                golesL.forEach(g => { if (nombreLimpio(g) === jugador && !g.includes('(e/c)')) { golesJugador++; } });
                // Buscar e/c en goles_l (el jugador local cometió e/c, anotado del lado local)
                golesL.forEach(g => { if (nombreLimpio(g) === jugador && g.includes('(e/c)')) { golesJugador++; esEC = true; } });
                if (golesJugador > 0) { equipoEnEstePartido = p.l; condicion = 'Local'; rival = p.v; }
            } else if (equiposBuscarFixture.includes(p.v)) {
                // Buscar goles normales en goles_v
                golesV.forEach(g => { if (nombreLimpio(g) === jugador && !g.includes('(e/c)')) { golesJugador++; } });
                // Buscar e/c en goles_v (el jugador visitante cometió e/c, anotado del lado visitante)
                golesV.forEach(g => { if (nombreLimpio(g) === jugador && g.includes('(e/c)')) { golesJugador++; esEC = true; } });
                if (golesJugador > 0) { equipoEnEstePartido = p.v; condicion = 'Visitante'; rival = p.l; }
            }

            if (golesJugador > 0 && equipoEnEstePartido) {
                const escRival = cat === 'federala'
                    ? (BD_EQUIPOS.federala.find(e => e.nombre === rival)?.clase || BD_EQUIPOS.federala_nonagonal.find(e => e.nombre === rival)?.clase || '')
                    : (BD_EQUIPOS[cat]?.find(e => e.nombre === rival)?.clase || '');
                const escPropio = cat === 'federala'
                    ? (BD_EQUIPOS.federala.find(e => e.nombre === equipoEnEstePartido)?.clase || BD_EQUIPOS.federala_nonagonal.find(e => e.nombre === equipoEnEstePartido)?.clase || '')
                    : (BD_EQUIPOS[cat]?.find(e => e.nombre === equipoEnEstePartido)?.clase || '');
                if (!partidosPorEquipo[equipoEnEstePartido]) partidosPorEquipo[equipoEnEstePartido] = [];
                const etiquetaTorneo = (origen === 'total' && cat === catPerfil) ? 'Apertura' : catLabels[cat];
                partidosPorEquipo[equipoEnEstePartido].push({ fecha: p.dia || '', torneo: etiquetaTorneo, condicion, rival, escRival, escPropio, resultado: `${p.gl}-${p.gv}`, goles: golesJugador, esEC });
            }
        });
    });
    if (origen === 'total' && catPerfil) {
        const fuenteClausura = catPerfil === 'oficial' ? BD_GOLEADORES_CLAUSURA_OFICIAL
            : catPerfil === 'promocional' ? BD_GOLEADORES_CLAUSURA_PROMOCIONAL
            : catPerfil === 'femenino' ? BD_GOLEADORAS_CLAUSURA_FEM
            : null;
        const equiposBuscarClausura = alias ? alias.equipos : [equipo];
        (fuenteClausura || []).forEach(gc => {
            const nombreGc = gc.jugador || gc.jugadora;
            if (nombreGc !== jugador) return;
            if (!equiposBuscarClausura.includes(gc.equipo)) return;
            (gc.partidos || []).forEach(p => {
                const escRival = BD_EQUIPOS[catPerfil]?.find(e => e.nombre === p.rival)?.clase || '';
                if (!partidosPorEquipo[gc.equipo]) partidosPorEquipo[gc.equipo] = [];
                partidosPorEquipo[gc.equipo].push({ fecha: p.fecha || '', torneo: 'Clausura', condicion: p.condicion, rival: p.rival, escRival, resultado: `${p.gl}-${p.gv}`, goles: p.goles, esEC: false });
            });
        });
    }
    // Escudos
    const getEscudo = nombre => Object.values(BD_EQUIPOS).flat().find(e => e.nombre === nombre)?.clase || '';
    const escActual   = getEscudo(equipoActual);
    const escAnterior = cambioDeEquipo ? getEscudo(equipoAnterior) : null;

    // HTML del header
    let html = `
    <div style="display:flex;align-items:center;gap:8px;padding:8px 10px;background:#f5f5f5;border-bottom:1px solid #ddd;cursor:pointer;" onclick="navegar('goleadores', estadoAnterior.categoria || 'oficial')">
        <span style="font-size:16px;color:#00331a;">←</span>
        <span style="font-size:11px;color:#555;">Volver a Goleadores</span>
    </div>
    <div class="header-t" style="font-size:16px;text-align:center;padding:12px;">⚽ ${jugador}</div>`;

    if (cambioDeEquipo) {
        html += `<div style="display:flex;align-items:center;justify-content:center;gap:16px;padding:12px 14px;background:#f0f7f0;border-bottom:1px solid #c8e6c9;">
            <div style="display:flex;flex-direction:column;align-items:center;gap:4px;opacity:0.7;">
                <div class="escudo ${escAnterior}"></div>
                <div style="font-size:9px;color:#888;text-align:center;">Inició en<br><b>${equipoAnterior}</b></div>
            </div>
            <div style="font-size:18px;color:#aaa;">→</div>
            <div style="display:flex;flex-direction:column;align-items:center;gap:4px;">
                <div class="escudo ${escActual}"></div>
                <div style="font-size:9px;color:#004d26;text-align:center;">Club actual<br><b>${equipoActual}</b></div>
            </div>
        </div>`;
    } else {
        const totalGApertura = (partidosPorEquipo[equipo]||[]).filter(p=>!p.esEC).reduce((a,p)=>a+p.goles,0);
        const totalG = (origen === 'total' && totalOverride !== undefined) ? Number(totalOverride) : totalGApertura;
        const etiquetaG = origen === 'total' ? 'en el año 2026' : 'en la temporada 2026';
        const escudoEq = getEscudo(equipo);
        html += `<div style="display:flex;align-items:center;gap:10px;padding:10px 14px;background:#f0f7f0;border-bottom:1px solid #c8e6c9;">
            <div class="escudo ${escudoEq}"></div>
            <div><div style="font-size:13px;font-weight:bold;">${equipo}</div>
            <div style="font-size:11px;color:#555;">${totalG} gol${totalG!==1?'es':''} ${etiquetaG}</div></div>
        </div>`;
    }

    // Función auxiliar para renderizar una tabla de partidos
    const renderTabla = (lista) => {
        if (!lista || lista.length === 0) return `<div style="text-align:center;padding:12px;color:#999;font-size:11px;">Sin goles registrados</div>`;
        let t = `<div style="font-size:11px;">
            <div style="display:flex;background:#eee;font-weight:bold;padding:5px 8px;border-bottom:2px solid #ccc;font-size:10px;">
                <div style="width:70px;flex-shrink:0;">Fecha</div>
                <div style="flex:1;">Rival</div>
                <div style="width:40px;text-align:center;">Res.</div>
                <div style="width:30px;text-align:center;">⚽</div>
            </div>`;
        lista.forEach(p => {
            t += `<div style="display:flex;align-items:center;padding:5px 8px;border-bottom:1px solid #eee;">
                <div style="width:70px;flex-shrink:0;font-size:9px;color:#666;line-height:1.4;">${p.fecha}<br><span style="color:#bbb;">${p.torneo.replace('Torneo ','')}</span></div>
                <div style="flex:1;display:flex;align-items:center;gap:4px;overflow:hidden;">
                    <div class="escudo ${p.escRival}" style="flex-shrink:0;"></div>
                    <span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${p.condicion === 'Local' ? 'vs' : 'en'} ${p.rival}</span>
                </div>
                <div style="width:40px;text-align:center;font-size:11px;">${p.resultado}</div>
                <div style="width:30px;text-align:center;font-weight:bold;">${p.goles}${p.esEC ? '*' : ''}</div>
            </div>`;
        });
        t += `</div>`;
        return t;
    };

    if (cambioDeEquipo) {
        // Tabla del equipo anterior
        const listAnterior = partidosPorEquipo[equipoAnterior] || [];
        const listActual   = partidosPorEquipo[equipoActual]   || [];
        const totalAnterior = listAnterior.filter(p=>!p.esEC).reduce((a,p)=>a+p.goles,0);
        const totalActual   = listActual.filter(p=>!p.esEC).reduce((a,p)=>a+p.goles,0);

        html += `<div style="display:flex;align-items:center;gap:6px;padding:6px 10px;background:#f9f9f9;border-bottom:1px solid #ddd;">
            <div class="escudo ${escAnterior}" style="opacity:0.7;"></div>
            <span style="font-size:11px;font-weight:bold;color:#555;">${equipoAnterior}</span>
            <span style="font-size:10px;color:#999;margin-left:4px;">${totalAnterior} gol${totalAnterior!==1?'es':''}</span>
        </div>`;
        html += renderTabla(listAnterior);

        html += `<div style="display:flex;align-items:center;gap:6px;padding:6px 10px;background:#f0f7f0;border-bottom:1px solid #c8e6c9;">
            <div class="escudo ${escActual}"></div>
            <span style="font-size:11px;font-weight:bold;color:#004d26;">${equipoActual} <span style="font-size:9px;font-weight:normal;background:#004d26;color:#fff;border-radius:3px;padding:1px 4px;">actual</span></span>
            <span style="font-size:10px;color:#555;margin-left:4px;">${totalActual} gol${totalActual!==1?'es':''}</span>
        </div>`;
        html += renderTabla(listActual);
    } else {
        const lista = Object.values(partidosPorEquipo).flat();
        if (lista.length === 0) {
            html += `<div style="text-align:center;padding:20px;color:#999;font-size:12px;">Sin partidos registrados</div>`;
        } else {
            html += `<div class="header-t">PARTIDOS</div>`;
            html += renderTabla(lista);
        }
    }

    return html;
}

