function generarTabla(tor, cat) {
    // Usar posiciones manuales si están disponibles (excepto tabla anual)
    const posManual = tor !== 'anual' && tor !== 'acumulada' ? BD_POSICIONES[cat]?.[tor] : null;
    let stats;
    if (posManual) {
        stats = posManual;
    } else {
        stats = BD_EQUIPOS[cat].map(e => ({...e, pj:0, pg:0, pe:0, pp:0, gf:0, gc:0, pts:0}));
        let partidos = [];
        if (tor === 'clausura' && (cat === 'oficial' || cat === 'promocional')) {
            partidos = BD_FIXTURES[cat].clausura.flatMap(f => f.partidos);
        } else if (tor === 'acumulada' && (cat === 'oficial' || cat === 'promocional')) {
            partidos = [
                ...BD_FIXTURES[cat].apertura.flatMap(f => f.partidos),
                ...BD_FIXTURES[cat].clausura.flatMap(f => f.partidos)
            ];
        } else if (cat === 'federala') {
            partidos = BD_FIXTURES.federala.posiciones.flatMap(f => f.partidos);
        } else if (cat === 'segundafemenino') {
            partidos = BD_FIXTURES.segundafemenino.torneo2026.flatMap(f => f.partidos);
        } else {
            partidos = BD_FIXTURES[cat].apertura.flatMap(f => f.partidos);
        }
        partidos.forEach(p => {
            if(p.gl !== null) {
                const l = stats.find(x => x.nombre === p.l), v = stats.find(x => x.nombre === p.v);
                if (!l || !v) return;
                l.pj++; v.pj++; l.gf += p.gl; l.gc += p.gv; v.gf += p.gv; v.gc += p.gl;
                if(p.gl > p.gv) { l.pg++; l.pts += 3; v.pp++; } else if(p.gv > p.gl) { v.pg++; v.pts += 3; l.pp++; } else { l.pe++; v.pe++; l.pts++; v.pts++; }
            }
        });
        stats.sort((a,b) => b.pts - a.pts || (b.gf-b.gc) - (a.gf-a.gc));
    }
    const catLabel = cat === 'femenino' ? 'PRIMERA FEMENINO' : cat === 'segundafemenino' ? 'SEGUNDA FEMENINO' : cat.toUpperCase();
    const titulo = tor === 'clausura' ? 'POSICIONES CLAUSURA' : tor === 'acumulada' ? 'TABLA ACUMULADA' : tor === 'anual' ? 'TABLA ACUMULADA' : 'POSICIONES';
    let html = `<div class="header-t">${titulo} - ${catLabel}</div><table>
    <thead><tr><th style="width:25px;">#</th><th style="text-align:left;padding-left:8px;">Equipo</th><th class="c-stat">PJ</th><th class="c-stat">PG</th><th class="c-stat">PE</th><th class="c-stat">PP</th><th class="c-stat">GF</th><th class="c-stat">GC</th><th class="c-stat">Dif</th><th class="c-stat">Pts</th></tr></thead><tbody>`;
    
    stats.forEach((e, i) => {
        let cl = "";
        if (tor !== 'anual' && tor !== 'acumulada' && cat === 'femenino') {
            if (i < 4) cl = "p-playoff";
            else cl = "p-desc";
        } else if (tor !== 'anual' && tor !== 'acumulada' && cat === 'segundafemenino') {
            if (i < 2) cl = "p-playoff";
            else if (i < 6) cl = "p-azul";
            else cl = "";
        } else if (tor !== 'anual' && tor !== 'acumulada' && i < 4) cl = "p-playoff";
        else if (tor === 'anual' || tor === 'acumulada') {
            if (cat === 'oficial') {
                if (i === 6) cl = "p-promo";
                if (i === 7) cl = "p-desc";
            } else if (cat === 'promocional') {
                if (i === 0) cl = "p-playoff";
            }
        }
        html += `<tr class="${cl}"><td class="c-pos">${i+1}</td><td class="c-equipo">${e.nombre}</td><td class="c-stat">${e.pj}</td><td class="c-stat">${e.pg}</td><td class="c-stat">${e.pe}</td><td class="c-stat">${e.pp}</td><td class="c-stat">${e.gf}</td><td class="c-stat">${e.gc}</td><td class="c-stat">${e.gf-e.gc}</td><td class="c-stat"><b>${e.pts}</b></td></tr>`;
    });
if (tor === 'apertura' && cat === 'oficial') {
    return html + "</tbody></table><div style='background:#f9f9f9; padding:4px 8px; font-size:10px; text-align:center; color:#555;'><b>(C)</b> Clasificado<br><b>(X)</b> Eliminado<br>📌 Puntos en juego: <b>Torneo finalizado</b></div>";
}
if (tor === 'clausura' && cat === 'oficial') {
    return html + "</tbody></table><div style='background:#f9f9f9; padding:4px 8px; font-size:10px; text-align:center; color:#555;'>📌 Puntos en juego: <b>30</b> tras finalizar la fecha 4</div>";
}
if (tor === 'clausura' && cat === 'femenino') {
    const posAcum = BD_POSICIONES['femenino']?.['acumulada'] || [];
    let htmlAcum = '';
    if (posAcum.length > 0) {
        htmlAcum += `<div class="header-t">TABLA ACUMULADA — 1° FEMENINO 2026</div>`;
        htmlAcum += `<table><thead><tr>
            <th style="width:25px;">#</th>
            <th style="text-align:left;padding-left:8px;">Equipo</th>
            <th class="c-stat">PJ</th><th class="c-stat">PG</th><th class="c-stat">PE</th>
            <th class="c-stat">PP</th><th class="c-stat">GF</th><th class="c-stat">GC</th>
            <th class="c-stat">Dif</th><th class="c-stat">Pts</th>
        </tr></thead><tbody>`;
        posAcum.forEach((e, i) => {
    const dif = e.gf - e.gc;
    const rowClass = i === 6 ? 'style="background:#fff3cd;"' : i === 7 ? 'style="background:#fde8e8;"' : '';
    htmlAcum += `<tr ${rowClass}>
                <td class="c-pos">${i+1}</td>
                <td class="c-equipo"><div class="escudo ${e.clase}"></div> ${e.nombre}</td>
                <td class="c-stat">${e.pj}</td><td class="c-stat">${e.pg}</td><td class="c-stat">${e.pe}</td>
                <td class="c-stat">${e.pp}</td><td class="c-stat">${e.gf}</td><td class="c-stat">${e.gc}</td>
                <td class="c-stat">${dif > 0 ? '+'+dif : dif}</td><td class="c-stat"><b>${e.pts}</b></td>
            </tr>`;
        });
        htmlAcum += `</tbody></table>`;
    }
    return html + "</tbody></table><div style='background:#f9f9f9; padding:4px 8px; font-size:10px; text-align:center; color:#555;'>📌 Puntos en juego: <b>30</b> tras la fecha 4<br><b>(A)</b> Ganador del Apertura<br><b>(*)</b> El partido entre Tiro Federal y Municipales de la fecha 3 (1-3) se les dio por perdido a ambos</div>" + htmlAcum;
}
if (tor === 'clausura' && cat === 'promocional') {
    return html + "</tbody></table><div style='background:#f9f9f9; padding:4px 8px; font-size:10px; text-align:center; color:#555;'>📌 Puntos en juego: <b>30</b> tras la fecha 4<br><b>(A)</b> Ganador del Apertura</div>";
}
if (tor === 'apertura' && cat === 'promocional') {
    return html + "</tbody></table><div style='background:#f9f9f9; padding:4px 8px; font-size:10px; text-align:center; color:#555;'><b>(X)</b> Eliminado<br>📌 Puntos en juego: <b>Torneo finalizado</b></b></div>";
}
    if (tor === 'apertura' && cat === 'femenino') {
        return html + "</tbody></table><div style='background:#f9f9f9; padding:4px 8px; font-size:10px; text-align:center; color:#555;'><b>(C)</b> Clasificado<br><b>(X)</b> Eliminado<br>📌 Puntos en juego: <b>Torneo finalizado</b></div>";
    }
    if (tor === 'torneo2026' && cat === 'segundafemenino') {
        return html + "</tbody></table><div style='background:#f9f9f9; padding:4px 8px; font-size:10px; text-align:center; color:#555;'><b>(C)</b> Clasificado<br>📌 Puntos en juego: <b>18</b> para los equipos que jugaron 18 partidos y <b>15</b> para los equipos que jugaron 19 partidos</div>";
    }
    return html + "</tbody></table>";
}


